*{box-sizing:border-box}html{background:var(--ink);scroll-behavior:smooth;scrollbar-color:var(--red) var(--paper)}body{margin:0;color:var(--ink);font:17px/1.6 Georgia,serif;background:var(--paper)}::selection{background:var(--gold);color:var(--ink)}a{color:inherit;text-underline-offset:4px}a:hover{color:var(--red)}button{font:inherit;color:inherit;cursor:pointer;min-height:46px;border:1px solid var(--ink);background:transparent;padding:9px 16px;border-radius:0}button:hover:not(:disabled){background:var(--wash)}button:disabled{cursor:default;opacity:.55}button:focus-visible,a:focus-visible{outline:3px solid var(--red);outline-offset:4px}button.primary{background:var(--ink);color:var(--paper)}button.primary:hover:not(:disabled){background:#26545d}button[aria-pressed=true]{background:var(--gold)}header,main,footer{max-width:1240px;margin:auto;padding-inline:var(--space)}nav{display:flex;justify-content:space-between;gap:18px;padding-block:20px;border-bottom:1px solid var(--ink);font:15px/1.5 system-ui,sans-serif}nav span{font-variant-numeric:tabular-nums}h1,h2,h3{font-family:Brygada,Georgia,serif;font-weight:650;line-height:1.04;text-wrap:balance}h1{font-size:clamp(3.1rem,7.4vw,6rem);letter-spacing:-.035em;margin:28px 0 12px}header p{max-width:64ch;margin:0 0 26px;font-size:19px}.masthead{position:relative}.masthead h1 em{color:var(--red);font-weight:550}main{padding-top:8px;padding-bottom:54px}.progress{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding-bottom:20px;font:15px/1.5 system-ui,sans-serif}.progress span{border-bottom:2px solid var(--wash);padding:8px 12px}.progress span.current{border-color:var(--red);font-weight:700}.progress span.done{border-color:var(--green)}
.sheet{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(260px,1fr);border-top:2px solid var(--ink);gap:0 38px}.story{min-width:0;padding-top:26px}.story h2{font-size:clamp(2rem,4vw,3rem);margin:0 0 12px}.story .deck{font-style:italic;margin:0 0 20px;color:var(--red)}figure{margin:0 0 20px}figure img{display:block;width:100%;aspect-ratio:1.5;object-fit:contain}figcaption{font:13px/1.5 system-ui,sans-serif;margin-top:7px}.passage{font-size:clamp(21px,2.1vw,27px);line-height:1.95;margin:14px 0 24px;max-width:65ch}.anchor{display:inline;font:inherit;line-height:inherit;padding:2px 3px;min-height:44px;border:0;border-bottom:1px dashed var(--red);box-decoration-break:clone;-webkit-box-decoration-break:clone;text-align:left;color:var(--red)}.anchor:hover:not(:disabled){background:var(--gold);color:var(--ink)}.anchor.fixed{color:var(--green);border-bottom-style:solid}.anchor:disabled{opacity:1}.margin{padding-top:26px}.margin h3{font-size:26px;margin:0 0 12px}.margin .instruction{font:15px/1.6 system-ui,sans-serif;margin-bottom:18px}.note{display:block;width:100%;padding:17px 0;text-align:left;border:0;border-top:1px solid var(--ink);font:17px/1.6 Georgia,serif;position:relative}.note[aria-pressed=true]{background:var(--gold);padding-inline:14px}.note small{display:block;font:700 12px/1.5 system-ui,sans-serif;letter-spacing:.04em;color:var(--red);margin-bottom:4px}.note[aria-pressed=true] small{color:var(--ink)}.note.solved{color:var(--green)}.note.solved small{color:var(--green)}.note:disabled{opacity:1}.tools{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0}.feedback{min-height:82px;border-top:1px solid var(--ink);padding-top:14px;margin:20px 0 0;font:16px/1.6 system-ui,sans-serif}.hint{font-style:italic;color:var(--red);min-height:28px}.end{background:var(--ink);color:var(--paper);padding:30px;margin-top:30px}.end h2{font-size:36px;margin:0 0 16px}.end button{color:var(--paper);border-color:var(--paper)}.end button:hover{background:#26545d}.end p{max-width:66ch}footer{border-top:1px solid var(--ink);padding-block:26px;font:15px/1.7 system-ui,sans-serif}footer p{max-width:75ch}.about{max-width:70ch;font-size:16px} .about summary{cursor:pointer;padding-block:12px;text-decoration:underline;text-underline-offset:4px} [hidden]{display:none!important}
